<?php
session_start();
if (empty($_SESSION['user_id'])) { header('Location: login.php'); exit; }
if (strtolower((string)($_SESSION['user_role'] ?? 'student')) !== 'student') { http_response_code(403); exit('This page is for student accounts.'); }
$id=(int)$_SESSION['user_id'];
function ach_h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
$attempts=0;$unique=0;$active=0;$days=[];$error='';
try {
 $db=new PDO('mysql:host=127.0.0.1;port=3306;dbname=kanji_master;charset=utf8mb4','root','root',array(PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC));
 $s=$db->prepare('SELECT COUNT(*) attempts, COUNT(DISTINCT kanji_id) unique_kanji, COUNT(DISTINCT DATE(created_at)) active_days FROM practice_attempts WHERE user_id=?');$s->execute(array($id));$r=$s->fetch();
 $attempts=(int)$r['attempts'];$unique=(int)$r['unique_kanji'];$active=(int)$r['active_days'];
 $s=$db->prepare('SELECT DISTINCT DATE(created_at) d FROM practice_attempts WHERE user_id=? ORDER BY d DESC');$s->execute(array($id));foreach($s->fetchAll() as $row)$days[]=$row['d'];
} catch(Throwable $e){error_log('Kanji achievements: '.$e->getMessage());$error='Could not load achievements. Check that MAMP/MySQL is running and the practice_attempts table exists.';}
$today=date('Y-m-d');$set=array_fill_keys($days,true);$streak=0;$date=isset($set[$today])?$today:date('Y-m-d',strtotime('-1 day'));while(isset($set[$date])){$streak++;$date=date('Y-m-d',strtotime($date.' -1 day'));}
$badges=array(
 array('icon'=>'🌱','title'=>'First Step','desc'=>'Save your first writing practice.','target'=>1,'value'=>$attempts,'unit'=>'attempts'),
 array('icon'=>'✍️','title'=>'Practice Pro','desc'=>'Save 10 writing-practice attempts.','target'=>10,'value'=>$attempts,'unit'=>'attempts'),
 array('icon'=>'💪','title'=>'Dedicated Learner','desc'=>'Save 50 writing-practice attempts.','target'=>50,'value'=>$attempts,'unit'=>'attempts'),
 array('icon'=>'🏅','title'=>'Kanji Explorer','desc'=>'Practise 10 different kanji.','target'=>10,'value'=>$unique,'unit'=>'kanji'),
 array('icon'=>'🗓️','title'=>'Regular Learner','desc'=>'Practise on 7 different calendar days.','target'=>7,'value'=>$active,'unit'=>'days'),
 array('icon'=>'🔥','title'=>'Three-Day Streak','desc'=>'Practise on 3 consecutive days.','target'=>3,'value'=>$streak,'unit'=>'day streak')
);
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Achievements | Kanji Master</title><style>*{box-sizing:border-box}body{margin:0;background:#0b1020;color:#f8fafc;font:15px/1.55 Arial,sans-serif}a{color:#c7d2fe;text-decoration:none}header{display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap;padding:18px 4%;background:#111827;border-bottom:1px solid #263247}.brand{font-weight:800}.brand span{color:#a5b4fc}nav{display:flex;gap:8px;flex-wrap:wrap}nav a{padding:8px 10px;border:1px solid #334155;border-radius:9px}main{width:min(1000px,94%);margin:30px auto 60px}.muted{color:#cbd5e1}.summary{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:14px;margin:22px 0}.panel,.badge{background:#151d31;border:1px solid #334155;border-radius:16px;padding:20px}.metric{font-size:32px;font-weight:800}.label{font-size:13px;color:#cbd5e1}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(245px,1fr));gap:14px}.badge{display:flex;gap:14px;align-items:flex-start}.badge.earned{border-color:#2c8b70;background:#12302d}.icon{font-size:32px}.badge h2{font-size:18px;margin:0 0 5px}.badge p{margin:0 0 10px;color:#cbd5e1;font-size:13px}.pill{font-size:11px;font-weight:bold;border-radius:99px;padding:5px 8px;background:#334155;color:#e2e8f0;display:inline-block}.earned .pill{background:#065f46;color:#d1fae5}.track{height:7px;background:#273449;border-radius:99px;overflow:hidden;margin:9px 0}.fill{height:100%;background:#818cf8}.notice{padding:12px;background:#7f1d1d;color:#fecaca;border-radius:10px}@media(max-width:600px){.badge,.panel{padding:15px}}</style></head><body><header><div class="brand">日本語 <span>Kanji Master</span> · Achievements</div><nav><a href="dashboard.php">← Dashboard</a><a href="practice.php">Writing practice</a><a href="study_streak.php">Study streak</a><a href="logout.php">Log out</a></nav></header><main><p class="label">CELEBRATE YOUR PROGRESS</p><h1>My achievements</h1><p class="muted">Earn badges by practising regularly and exploring different kanji. Progress updates from your saved writing-practice attempts.</p><?php if($error):?><p class="notice"><?=ach_h($error)?></p><?php endif;?><section class="summary"><div class="panel"><div class="label">Badges earned</div><div class="metric"><?=count(array_filter($badges,function($b){return $b['value'] >= $b['target'];}))?> / <?=count($badges)?></div></div><div class="panel"><div class="label">Saved attempts</div><div class="metric"><?=number_format($attempts)?></div></div><div class="panel"><div class="label">Different kanji practised</div><div class="metric"><?=number_format($unique)?></div></div></section><section class="grid"><?php foreach($badges as $b):$earned=$b['value'] >= $b['target'];$progress=min(100,(int)round($b['value']/$b['target']*100));?><article class="badge <?=$earned?'earned':''?>"><div class="icon"><?=ach_h($b['icon'])?></div><div style="flex:1"><h2><?=ach_h($b['title'])?></h2><p><?=ach_h($b['desc'])?></p><span class="pill"><?=$earned?'✓ Earned':'In progress'?></span><div class="track"><div class="fill" style="width:<?=$progress?>%"></div></div><div class="label"><?=number_format(min($b['value'],$b['target']))?> / <?=number_format($b['target'])?> <?=ach_h($b['unit'])?></div></div></article><?php endforeach;?></section><p class="muted" style="font-size:13px;margin-top:20px">Badges are calculated from saved practice history; no extra data entry is needed.</p></main></body></html>